	error_reporting(0);
	
	class SimpleXmlParser
		{
			var $SimpleParser;
			var $feedUrl;

			var $title			= "";
			var $description	= "";
			var $link			= "";
			var $author			= "";
			var $pubDate		= "";
			var $insideitem		= false;
			var $tag			= "";
			var $count_results	= 0;
			var $total_results	= 0;
	
			function SimpleXmlParser($MyFeed, $results) 
				{		
					print "<table align='center' cellpadding='0' cellspacing='0' width='96%'>";
					
					$this->total_results	= $results;		
					$this->SimpleParser		= xml_parser_create();           
					$this->feedUrl			= $MyFeed;   
		
					xml_set_object($this->SimpleParser,$this);	
					xml_set_element_handler($this->SimpleParser, "XmlParserFirstElement", "XmlParserendElement");
					xml_set_character_data_handler($this->SimpleParser, "characterData");  
					
					$this->ParseFeed(); 
					
					print "</table><br>";	

				}
	
			function XmlParserFirstElement($parser, $tagName, $attrs) 
				{
					if ($this->insideitem) 
						{
							$this->tag			= $tagName;
						} 
					elseif ($tagName == "ITEM") 
						{
							$this->insideitem	= true;
						}
				}

			function XmlParserendElement($parser, $tagName)
				{
        			if ($tagName == "ITEM") 
        				{
							if ($this->count_results < $this->total_results) 
								{								
									print "<tr><td align='center' valign='top'>&nbsp;</td><td valign='top' style='padding-left:10;'><a target='_new' href='http://".$this->link."'>".htmlspecialchars(trim($this->title))."</a><br><p style='color:#808080;margin-left:0;'><small>".htmlspecialchars(trim($this->pubDate))."</small></p><p class='pNewsFeed'>".htmlspecialchars(trim($this->description))."</p><br><td></tr>";
																			
									$this->title = "";
									$this->description = "";
									$this->link = "";
									$this->pubDate = "";
									$this->insideitem = false;
								}
							$this->count_results = $this->count_results + 1;
						}
				}	
	
			function characterData($parser, $data) 
				{
					if ($this->insideitem) 
						{
							switch ($this->tag) 
							{
									case "TITLE":
										$this->title .= $data;
										break;
									case "DESCRIPTION":
										$this->description .= $data;
										break;
									case "LINK":
										$this->link .= $data;
										$pos = strpos($this->link, "*");
										if (!($pos === false)) 
											{				  
												$this->link  = substr($this->link , $pos + 1, 300);					  
											}
										$this->link = trim($this->link);
										$pos = strpos($this->link, "//");
										if (!($pos === false)) 
											{	  
												$this->link  = substr($this->link , $pos + 2, 300);					  
											}				  
										break;
									case "PUBDATE":
										$this->pubDate .= $data;
										break;										
								}
						}
				}

			function ParseFeed()
				{
					$data = file_get_contents($this->feedUrl);
					xml_parse($this->SimpleParser, $data);		
					xml_parser_free($this->SimpleParser);        
				}
		}
		 
?>
